using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    Task<List<Department>> GetDepartmentsAsync();
    Task<Department?> GetDepartmentAsync(int id);
    Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null, int? credits = null);
    Task<Course?> GetCourseAsync(int id);
    Task<List<Course>> GetFeaturedCoursesAsync();
    Task<Instructor?> GetInstructorAsync(int id);
    Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events and their significance." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen has over 15 years of experience in artificial intelligence and machine learning research. She holds a Ph.D. from MIT and has published over 50 peer-reviewed papers.", Email = "achen@university.edu", OfficeLocation = "Science Building 302" },
            new() { Id = 2, Name = "Dr. Robert Williams", Title = "Associate Professor of Mathematics", Bio = "Dr. Williams specializes in abstract algebra and number theory. He received his doctorate from Princeton and has been teaching for 10 years.", Email = "rwilliams@university.edu", OfficeLocation = "Math Hall 215" },
            new() { Id = 3, Name = "Dr. Maria Garcia", Title = "Professor of Physics", Bio = "Dr. Garcia is an experimental physicist whose research focuses on quantum optics. She has received multiple NSF grants and mentored dozens of graduate students.", Email = "mgarcia@university.edu", OfficeLocation = "Physics Lab 108" },
            new() { Id = 4, Name = "Prof. James Mitchell", Title = "Lecturer in English", Bio = "Prof. Mitchell is an award-winning author and literary critic. He holds an MFA in Creative Writing and has published three novels.", Email = "jmitchell@university.edu", OfficeLocation = "Humanities 420" },
            new() { Id = 5, Name = "Dr. Sarah Kim", Title = "Associate Professor of History", Bio = "Dr. Kim is a historian of early modern Europe with a focus on the Renaissance. She is the author of two critically acclaimed books.", Email = "skim@university.edu", OfficeLocation = "Liberal Arts 310" },
            new() { Id = 6, Name = "Dr. David Patel", Title = "Assistant Professor of Computer Science", Bio = "Dr. Patel researches distributed systems and cloud computing. Before academia, he spent five years as a software engineer at a major tech company.", Email = "dpatel@university.edu", OfficeLocation = "Science Building 318" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of computer science including problem solving, algorithms, data representation, and basic programming in Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Building 101", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Building 205", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 6, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Introduction to the theory and practice of artificial intelligence. Topics include search algorithms, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Building 310", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 42 },
            new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "Limits, continuity, differentiation of single-variable functions, applications of derivatives, introduction to integration, and the Fundamental Theorem of Calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Hall 100", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, IsFeatured = false, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 5, Code = "MATH 252", Title = "Linear Algebra", Description = "Systems of linear equations, matrices, determinants, vector spaces, linear transformations, eigenvalues and eigenvectors, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Hall 201", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, conservation of energy and momentum, rotational dynamics, fluid mechanics, and wave phenomena.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 100", DepartmentId = 3, DepartmentName = "Physics", InstructorId = 3, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 87 },
