@using UniversityCourseCatalog.Models

<div class="list-group">
    @foreach (var dept in Departments)
    {
        <a href="/catalog?departmentId=@dept.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
            <div>
                <strong>@dept.Abbreviation</strong> — @dept.Name
            </div>
            <span class="badge bg-primary rounded-pill">@(CourseCounts.GetValueOrDefault(dept.Id))</span>
        </a>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = default!;

    [Parameter]
    public Dictionary<int, int> CourseCounts { get; set; } = new();
}

@using UniversityCourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-5">
        <div class="input-group">
            <span class="input-group-text">🔍</span>
            <input type="text" class="form-control" placeholder="Search courses…"
                   value="@SearchTerm" @oninput="OnSearchInput" />
        </div>
    </div>
    <div class="col-md-3">
        <select class="form-select" value="@DepartmentId" @onchange="OnDepartmentChange">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <select class="form-select" value="@Credits" @onchange="OnCreditsChange">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public int DepartmentId { get; set; }
    [Parameter] public int Credits { get; set; }
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> DepartmentIdChanged { get; set; }
    [Parameter] public EventCallback<int> CreditsChanged { get; set; }
    [Parameter, EditorRequired] public List<Department> Departments { get; set; } = default!;
    [Parameter] public EventCallback OnClear { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
        => await SearchTermChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);

    private async Task OnDepartmentChange(ChangeEventArgs e)
        => await DepartmentIdChanged.InvokeAsync(int.TryParse(e.Value?.ToString(), out var v) ? v : 0);

    private async Task OnCreditsChange(ChangeEventArgs e)
        => await CreditsChanged.InvokeAsync(int.TryParse(e.Value?.ToString(), out var v) ? v : 0);

    private async Task ClearFilters() => await OnClear.InvokeAsync();
}

