@page "/"
@using UniversityCourseCatalog.Components.Catalog
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="px-4 py-5 text-center bg-light rounded-3 mb-4">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead mb-4">Browse courses, explore departments, and enroll for the upcoming semester.</p>
    <div class="d-grid gap-2 d-sm-flex justify-content-sm-center">
        <a href="/catalog" class="btn btn-primary btn-lg px-4 gap-3">Browse All Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary btn-lg px-4">Enroll Now</a>
    </div>
</div>

@if (_featuredCourses is null)
{
    <p class="text-center"><em>Loading…</em></p>
}
else
{
    <section class="mb-5">
        <h2 class="mb-3">⭐ Featured Courses</h2>
        <div class="row row-cols-1 row-cols-md-3 g-4">
            @foreach (var course in _featuredCourses)
            {
                <div class="col">
                    <FeaturedCourseCard Course="course" />
                </div>
            }
        </div>
    </section>

    <section>
        <h2 class="mb-3">Departments</h2>
        <DepartmentLinkList Departments="_departments" CourseCounts="_courseCounts" />
    </section>
}

@code {
    private List<Course>? _featuredCourses;
    private List<Department> _departments = new();
    private Dictionary<int, int> _courseCounts = new();

    protected override async Task OnInitializedAsync()
    {
        var coursesTask = CatalogService.GetFeaturedCoursesAsync();
        var departmentsTask = CatalogService.GetDepartmentsAsync();
        var allCoursesTask = CatalogService.GetCoursesAsync();

        await Task.WhenAll(coursesTask, departmentsTask, allCoursesTask);

        _featuredCourses = coursesTask.Result;
        _departments = departmentsTask.Result;
        _courseCounts = allCoursesTask.Result
            .GroupBy(c => c.DepartmentId)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

