@page "/catalog"
@using UniversityCourseCatalog.Components.Catalog
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CatalogFilters SearchTerm="@_searchTerm"
                SearchTermChanged="OnSearchTermChanged"
                DepartmentId="@_departmentId"
                DepartmentIdChanged="OnDepartmentIdChanged"
                Credits="@_credits"
                CreditsChanged="OnCreditsChanged"
                Departments="_departments"
                OnClear="ClearFilters" />

@if (_courses is null)
{
    <p><em>Loading courses…</em></p>
}
else if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your filters. Try broadening your search.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private List<Course>? _courses;
    private List<Department> _departments = new();
    private string _searchTerm = string.Empty;
    private int _departmentId;
    private int _credits;

    [SupplyParameterFromQuery(Name = "departmentId")]
    public int? QueryDepartmentId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (QueryDepartmentId.HasValue)
            _departmentId = QueryDepartmentId.Value;

        _departments = await CatalogService.GetDepartmentsAsync();
        await LoadCoursesAsync();
    }

    private async Task OnSearchTermChanged(string term)
    {
        _searchTerm = term;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentIdChanged(int id)
    {
        _departmentId = id;
        await LoadCoursesAsync();
    }

    private async Task OnCreditsChanged(int credits)
    {
        _credits = credits;
        await LoadCoursesAsync();
    }

    private async Task ClearFilters()
    {
        _searchTerm = string.Empty;
        _departmentId = 0;
        _credits = 0;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        _courses = await CatalogService.GetCoursesAsync(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _departmentId > 0 ? _departmentId : null,
            _credits > 0 ? _credits : null);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Components.Catalog
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Detail")</PageTitle>

@if (_course is null)
{
    <p><em>Loading course details…</em></p>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/catalog">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="d-flex justify-content-between align-items-start mb-3">
        <div>
            <h1>@_course.Title</h1>
            <span class="badge bg-primary fs-6 me-2">@_course.Code</span>
            <span class="badge bg-secondary fs-6">@_course.DepartmentName</span>
        </div>
        <a href="/enroll?courseId=@_course.Id" class="btn btn-success">Enroll in This Course</a>
    </div>

    <div class="row">
        <div class="col-lg-8">
            <h3>Description</h3>
            <p class="lead">@_course.Description</p>

            <h3 class="mt-4">Schedule &amp; Details</h3>
            <CourseScheduleInfo Course="_course" />
        </div>
        <div class="col-lg-4">
            <h3>Instructor</h3>
            @if (_instructor is not null)
            {
                <InstructorBio Instructor="_instructor" />
            }
            else
            {
                <p class="text-muted"><em>Instructor information unavailable.</em></p>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;
    private Instructor? _instructor;

    protected override async Task OnInitializedAsync()
    {
        _course = await CatalogService.GetCourseAsync(Id);
        if (_course is not null)
            _instructor = await CatalogService.GetInstructorAsync(_course.InstructorId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Components.Catalog
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request has been received and will be reviewed by the registrar's office.</p>
        <hr />
        <p class="mb-0"><a href="/catalog" class="alert-link">Return to catalog</a> or <a href="/enroll" class="alert-link" @onclick="Reset" @onclick:preventDefault>submit another request</a>.</p>
    </div>
}
else
{
    @if (_courses is null)
    {
        <p><em>Loading…</em></p>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <p class="text-muted mb-4">Complete the form below to request enrollment in a course. All fields marked are required.</p>
                <EnrollmentForm Model="_model" Courses="_courses" OnSubmit="HandleSubmit" IsSubmitting="_isSubmitting" />
            </div>
            <div class="col-lg-4">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">Need Help?</h5>
                        <p class="card-text">Contact the Registrar's Office at <strong>registrar@university.edu</strong> or visit Room 100 in the Administration Building.</p>
                    </div>
                </div>
            </div>
        </div>
    }
}

@code {
    private EnrollmentRequest _model = new();
    private List<Course>? _courses;
    private bool _submitted;
    private bool _isSubmitting;

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _courses = await CatalogService.GetCoursesAsync();
        if (PreselectedCourseId.HasValue)
            _model.CourseId = PreselectedCourseId.Value;
    }

    private async Task HandleSubmit(EnrollmentRequest request)
    {
        _isSubmitting = true;
        await CatalogService.SubmitEnrollmentRequestAsync(request);
        _isSubmitting = false;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new EnrollmentRequest();
        _submitted = false;
    }
}

