@page "/catalog"
@using UniversityCourseCatalog.Components.Catalog
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CatalogFilters SearchTerm="@_searchTerm"
                SearchTermChanged="OnSearchTermChanged"
                DepartmentId="@_departmentId"
                DepartmentIdChanged="OnDepartmentIdChanged"
                Credits="@_credits"
                CreditsChanged="OnCreditsChanged"
                Departments="_departments"
                OnClear="ClearFilters" />

@if (_courses is null)
{
    <p><em>Loading courses…</em></p>
}
else if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your filters. Try broadening your search.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private List<Course>? _courses;
    private List<Department> _departments = new();
    private string _searchTerm = string.Empty;
    private int _departmentId;
    private int _credits;

    [SupplyParameterFromQuery(Name = "departmentId")]
    public int? QueryDepartmentId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (QueryDepartmentId.HasValue)
            _departmentId = QueryDepartmentId.Value;

        _departments = await CatalogService.GetDepartmentsAsync();
        await LoadCoursesAsync();
    }

    private async Task OnSearchTermChanged(string term)
    {
        _searchTerm = term;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentIdChanged(int id)
    {
        _departmentId = id;
        await LoadCoursesAsync();
    }

    private async Task OnCreditsChanged(int credits)
    {
        _credits = credits;
        await LoadCoursesAsync();
    }

    private async Task ClearFilters()
    {
        _searchTerm = string.Empty;
        _departmentId = 0;
        _credits = 0;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        _courses = await CatalogService.GetCoursesAsync(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _departmentId > 0 ? _departmentId : null,
            _credits > 0 ? _credits : null);
    }
}

